s($,"e1I","aOS",()=>new A.brh(A.aq("[/\\\\]",!0,!1,!1,!1),A.aq("[^/\\\\]$",!0,!1,!1,!1),A.aq("^(\\\\\\\\[^\\\\]+\\\\[^\\\\/]+|[a-zA-Z]:[/\\\\])",!0,!1,!1,!1),A.aq("^[/\\\\](?![/\\\\])",!0,!1,!1,!1)))
s($,"e1H","ai0",()=>new A.bqm(A.aq("/",!0,!1,!1,!1),A.aq("(^[a-zA-Z][-+.a-zA-Z\\d]*://|[^/])$",!0,!1,!1,!1),A.aq("[a-zA-Z][-+.a-zA-Z\\d]*://[^/]*",!0,!1,!1,!1),A.aq("^/",!0,!1,!1,!1)))
